/** Typed view of the NDJSON contract with the native dictation helper. */

export interface HelperStatus {
  accessibility: boolean
  inputMonitoring: boolean
  secureInput: boolean
  /** Running dictation apps whose shortcuts may overlap (names only). */
  conflicts: string[]
  holdActive: boolean
  mouseActive: boolean
  /** Input Monitoring as macOS reports it; null when the helper does not say. */
  inputMonitoringAccess: 'granted' | 'denied' | 'not-determined' | null
  /**
   * What macOS does on its own when the Fn/Globe key is pressed: 0 nothing,
   * 1 change input source, 2 emoji and symbols, 3 start dictation. Null when
   * the setting cannot be read.
   */
  fnKeyAction: number | null
  /**
   * Windows: whether the low-level hooks are currently installed (false during a
   * detected loss, before the helper re-installs them). Null off Windows.
   */
  hooksLive?: boolean | null
}

export interface TargetDescription {
  snapshotId: string
  pid: number
  bundleId: string
  appName: string
  /** The app bundle on disk, used only to draw its icon. May be absent or empty. */
  appPath?: string
  hasElement: boolean
  accessibility: boolean
  role?: string
  secure?: boolean
  editable?: boolean
}

/** An installed app's own name and icon, found from its bundle identifier. Null when not installed. */
export interface AppInfoEntry {
  bundleId: string
  name: string | null
  /** A small PNG data URL. */
  icon: string | null
}

/** Guards for a delivery that edits text already in the field. */
export interface DeliveryGuards {
  /** Refuse unless the selection is exactly this text. */
  expectSelection?: string
  /** Select the one copy of this text in the field and replace it; refuse if it is not there once. */
  replace?: string
  /** After a confirmed insertion, keep the field so it can be read back for a few minutes. */
  watch?: boolean
}

/**
 * A read-back of a watched field. `ok` carries the field's text and whether it
 * still has the user's focus. gone: the field or its app no longer exists (a sent
 * message usually clears or removes it). secure: it became a password field.
 * unreadable: this control does not expose its text. too-long: over the size cap.
 */
export type FieldReading =
  | { state: 'ok'; value: string; focused: boolean }
  | { state: 'gone' | 'secure' | 'unreadable' | 'too-long' }

export type SelectionResult =
  | { ok: true; text: string }
  | { ok: false; reason: 'no-target' | 'focus-changed' | 'secure-field' | 'unavailable' }

export type HelperDeliveryOutcome = 'delivered' | 'uncertain' | 'refused' | 'failed'

/** Where the helper's time went for one insertion, whole milliseconds. Numbers only. */
export interface HelperDeliveryTimings {
  /** Re-validating the target right before touching it. */
  validateMs: number
  /** The insertion call itself. */
  insertMs: number
  /** Polling the control to see the text arrive. */
  confirmMs: number
  /** A fixed wait before restoring the clipboard when arrival cannot be seen. */
  settleMs: number
  /** Accessibility insertion was skipped because this app ignores it. */
  skippedAx: boolean
}

export interface HelperDelivery {
  outcome: HelperDeliveryOutcome
  reason?: string
  /** ax: macOS accessibility insertion. paste: clipboard and Cmd/Ctrl+V. type: Windows Unicode keystrokes. */
  method?: 'ax' | 'paste' | 'type'
  verified: boolean
  /** untouched | restored | user-changed | partial */
  clipboard: string
  timings?: HelperDeliveryTimings
}

export type HoldFailure = 'input-monitoring-denied' | 'unknown-key' | 'helper-unavailable'

/**
 * Mouse buttons are numbered from 0: 0 left, 1 right, 2 middle, 3 back, 4 forward,
 * then the extras. Only 2 and up may be a trigger; left and right click never.
 */
export const MIN_MOUSE_TRIGGER_BUTTON = 2
export const MAX_MOUSE_TRIGGER_BUTTON = 31

export function isAllowedMouseButton(value: unknown): value is number {
  return (
    typeof value === 'number' &&
    Number.isInteger(value) &&
    value >= MIN_MOUSE_TRIGGER_BUTTON &&
    value <= MAX_MOUSE_TRIGGER_BUTTON
  )
}

/** click: every press is a click (start, then stop). hold: hold to talk, double tap for hands-free. */
export const MOUSE_MODES = ['click', 'hold'] as const
export type MouseMode = (typeof MOUSE_MODES)[number]

export type MouseFailure = HoldFailure | 'invalid-button'

export type MouseStartResult =
  | {
      ok: true
      /** The helper consumes this button's events so other apps never see them. */ swallowing: boolean
    }
  | { ok: false; failure: MouseFailure }

export type MouseCaptureFailure =
  'primary-button' | 'timeout' | 'input-monitoring-denied' | 'helper-unavailable' | 'failed'

export type MouseCaptureResult =
  { ok: true; button: number } | { ok: false; failure: MouseCaptureFailure }

export const HOLD_KEYS = ['off', 'rightOption', 'rightControl', 'rightCommand', 'fn'] as const
export type HoldKey = (typeof HOLD_KEYS)[number]

/** What the helper could read about the microphone a session is recording from. */
export interface InputState {
  /** The device's mute switch, when it has one. */
  muted: boolean | null
  /** Input volume 0..1, when the device exposes one. */
  volume: number | null
}

/** Muted, or turned all the way down: either way the user will not be heard. */
export function micLooksMuted(state: InputState | null): boolean {
  if (!state) return false
  return state.muted === true || (state.volume !== null && state.volume <= 0)
}

/* ---- Windows delivery timing (must mirror engine/windows/dictation-helper/Delivery.cs) ---- */

/**
 * Per-character typing cost; matches Delivery.cs TypeEstimateMs: the 8 ms pacing, the per-keystroke
 * password/focus guard and the wait for the target to show it processed each key (30-35 ms measured
 * on Dev04 in Notepad and WinForms, besides the boundary pauses; the typing fallback is refused up
 * front for targets it cannot observe, such as Chromium apps).
 */
export const HELPER_TYPE_PER_CHAR_MS = 50
/** Extra pause at each word boundary (whitespace/punctuation). */
export const HELPER_TYPE_BOUNDARY_MS = 70
/** Fixed overhead for validation, confirm and settle in TypeEstimateMs. */
export const HELPER_TYPE_OVERHEAD_MS = 3_000
/** The helper's PasteEstimateMs (clipboard + Ctrl+V, start to settled). */
export const HELPER_PASTE_ESTIMATE_MS = 1_600
/** Allowance for the clipboard retry loop and the request's pipe/queue latency. */
export const HELPER_DELIVER_MARGIN_MS = 2_500

/**
 * The C# helper classifies each UTF-16 code unit it types as a slower "boundary" when
 * char.IsWhiteSpace(c) || char.IsPunctuation(c) is true, using .NET Framework 4.8's Unicode data.
 * JS \s and \p{P} disagree with that for a few dozen code units (e.g. U+0085 NEL, U+00AD soft
 * hyphen, U+00A7), which would mis-size the deliver deadline. To agree exactly, code unit for code
 * unit, this is the helper's own BMP classification captured from its __boundary-table op (one bit
 * per code unit, 8192 bytes). dictation-boundary-parity.test.ts verifies it against a fresh capture.
 */
const DOTNET_BOUNDARY_BMP_BASE64 =
  ''

let boundaryBits: Uint8Array | null = null

function boundaryTable(): Uint8Array {
  if (boundaryBits) return boundaryBits
  const binary = atob(DOTNET_BOUNDARY_BMP_BASE64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
  boundaryBits = bytes
  return bytes
}

/**
 * Whether one UTF-16 code unit is a typing "boundary" the way the C# helper counts it. Reads the
 * embedded .NET classification so TS and C# agree exactly.
 */
export function isTypingBoundaryUnit(codeUnit: number): boolean {
  if (codeUnit < 0 || codeUnit > 0xffff) return false
  const table = boundaryTable()
  return (table[codeUnit >> 3]! & (1 << (codeUnit & 7))) !== 0
}

/**
 * The helper's own worst-case estimate for delivering `text`, start to settled, matching the C#
 * TypeEstimateMs code unit for code unit. The client sizes its wait and the deadline from this so a
 * short transcript can still fall back to typing under clipboard contention rather than being
 * refused `deadline-exceeded`. Note the caller clamps the deadline at 60 s, so for very long text
 * the "estimate + margin" relation holds only up to that clamp (the helper's own deadline check uses
 * the same clamped value, so they still agree).
 */
export function helperDeliverEstimateMs(text: string): number {
  const normalized = text.replace(/\r\n/g, '\n')
  let boundaries = 0
  for (let i = 0; i < normalized.length; i++) {
    if (isTypingBoundaryUnit(normalized.charCodeAt(i))) boundaries++
  }
  const typing =
    normalized.length * HELPER_TYPE_PER_CHAR_MS +
    boundaries * HELPER_TYPE_BOUNDARY_MS +
    HELPER_TYPE_OVERHEAD_MS
  return Math.max(HELPER_PASTE_ESTIMATE_MS, typing)
}
